  "implementation": "import math\\ndef solve(case):\\n    vectors = case[\\\"sentence_vectors\\\"]\\n    query = case[\\\"query_vector\\\"]\\n    cw = case[\\\"context_weight\\\"]\\n    n = len(vectors)\\n    def cosine_sim(u, v):\\n        dot = sum(a*b for a,b in zip(u,v))\\n        norm_u = math.sqrt(sum(a*a for a in u))\\n        norm_v = math.sqrt(sum(a*a for a in v))\\n        if norm_u == 0 or norm_v == 0:\\n            return 0.0\\n        return dot / (norm_u * norm_v)\\n    scores = []\\n    for i, v in enumerate(vectors):\\n        sim_q = cosine_sim(v, query)\\n        context_scores = [cosine_sim(v, vectors[j]) for j in range(n) if j != i]\\n        sim_c = sum(context_scores) / len(context_scores) if context_scores else 0.0\\n        score = (1 - cw) * sim_q + cw * sim_c\\n        scores.append(score)\\n    ranked = sorted(range(n), key=lambda i: (-scores[i], i))\\n    ranking = ranked\\n    ordered_scores = [scores[i] for i in ranking]\\n    return {\\\"ranking\\\": ranking, \\\"scores\\\": ordered_scores}"
}
